import React from 'react';
import * as styles from './GridBackground.css';

const GridBackground: React.FunctionComponent = () => {
    return (
        <div className={styles.gridWrapper}>
            <svg
                className={styles.gridSvg}
                viewBox="100 100 1500 1019"

                fill="none"
                    xmlns="http://www.w3.org/2000/svg"
                    xmlnsXlink="http://www.w3.org/1999/xlink"
                    >
                    <rect x="-1027" width="3112" height="1280" fill="url(#pattern0_26172_1021)"/>
                    <defs>
                        <pattern id="pattern0_26172_1021" patternContentUnits="objectBoundingBox" width="1" height="1">
                            <use xlinkHref="#image0_26172_1021" transform="scale(0.000321337 0.00078125)"/>
                        </pattern>
                        <image id="image0_26172_1021" width="3122" height="1280" preserveAspectRatio="none" xlinkHref="data:image/png;base64,"/>
                </defs>
            </svg>
            <div className={styles.gridFade} />
        </div>
    );
};

export default GridBackground;


